function cpToggleMerchantTab(group_id, customer_id) {
  $.ajax({
    url: 'index.php?route=extension/module/cp_merchant/checkgroup&user_token={{ user_token }}&group_id=' + group_id,
    dataType: 'json',
    success: function(json) {
      if (json['is_merchant']) {
        $('#tab-merchant-li').show();
        if (customer_id) {
          $('#tab-merchant').load('index.php?route=extension/module/cp_merchant/form&user_token={{ user_token }}&customer_id=' + customer_id);
        } else {
          $('#tab-merchant').html('<p class="text-muted">Save the customer first to manage the merchant application.</p>');
        }
      } else {
        $('#tab-merchant-li').hide();
      }
    }
  });
}
$('select[name=\'customer_group_id\']').on('change', function() {
  cpToggleMerchantTab(this.value, {{ customer_id ? customer_id : 0 }});
});
cpToggleMerchantTab($('select[name=\'customer_group_id\']').val(), {{ customer_id ? customer_id : 0 }});

// Also persist the merchant tab whenever the main customer Save button
// is clicked, so admins don't have to remember to use the tab's own
// separate Save button. Guarded on the tab actually having been loaded
// (its fields present in the DOM) — otherwise, for a customer whose
// merchant tab was never opened this session, we'd silently POST empty
// values and wipe out their real data.
$(document).on('click', '#button-save', function() {
  var customerId = {{ customer_id ? customer_id : 0 }};
  var $fields = $('#tab-merchant :input.cp-field');

  if (!customerId || !$fields.length) {
    return;
  }

  var data = $fields.serialize()
    + '&' + $('#tab-merchant select[name="cp_status"]').serialize()
    + '&' + $('#tab-merchant input[name="shipping_same_as_billing"]').serialize()
    + '&customer_id=' + customerId;

  $.ajax({
    url: 'index.php?route=extension/module/cp_merchant/save&user_token={{ user_token }}',
    type: 'post',
    data: data,
    dataType: 'json'
  });
});

if ($this->customer->isLogged()) {
  $cp_merchant_group_ids = (array)$this->config->get('module_cp_merchant_group_ids');

  if (in_array((int)$this->customer->getGroupId(), array_map('intval', $cp_merchant_group_ids), true)) {
    $this->load->model('account/merchant');

    $cp_application = $this->model_account_merchant->getApplication($this->customer->getId());

    if (!$cp_application || $cp_application['status'] == 'incomplete') {
      $this->response->redirect($this->url->link('account/merchant', '', true));
    }
  }
}
